const STATE_FULL: Record<string, string> = {"AL": "Alabama", "AK": "Alaska", "AZ": "Arizona", "AR": "Arkansas", "CA": "California", "CO": "Colorado", "CT": "Connecticut", "DE": "Delaware", "FL": "Florida", "GA": "Georgia", "HI": "Hawaii", "ID": "Idaho", "IL": "Illinois", "IN": "Indiana", "IA": "Iowa", "KS": "Kansas", "KY": "Kentucky", "LA": "Louisiana", "ME": "Maine", "MD": "Maryland", "MA": "Massachusetts", "MI": "Michigan", "MN": "Minnesota", "MS": "Mississippi", "MO": "Missouri", "MT": "Montana", "NE": "Nebraska", "NV": "Nevada", "NH": "New Hampshire", "NJ": "New Jersey", "NM": "New Mexico", "NY": "New York", "NC": "North Carolina", "ND": "North Dakota", "OH": "Ohio", "OK": "Oklahoma", "OR": "Oregon", "PA": "Pennsylvania", "RI": "Rhode Island", "SC": "South Carolina", "SD": "South Dakota", "TN": "Tennessee", "TX": "Texas", "UT": "Utah", "VT": "Vermont", "VA": "Virginia", "WA": "Washington", "WV": "West Virginia", "WI": "Wisconsin", "WY": "Wyoming", "DC": "District of Columbia"};

export function applyRealPhotoPatch(towers: WaterTower[]): WaterTower[] {
  return towers.map((t) => {
    const p = PHOTO_ONLY[t.number];
    if (p) {
      return { ...t, photos: [{ url: p.url, caption: `${t.name} in ${t.city}, ${t.state}.`, credit: p.credit, isHero: true }] };
    }
    const r = REPLACEMENTS[t.number];
    if (!r) return t;
    const id = r.name.toLowerCase().replace(/[^a-z0-9]+/g, '-');
    const coordinates = `${Math.abs(r.lat).toFixed(4)}° ${r.lat >= 0 ? 'N' : 'S'}, ${Math.abs(r.lng).toFixed(4)}° ${r.lng >= 0 ? 'E' : 'W'}`;
    return {
      ...t, id, name: r.name, city: r.city, state: r.state,
      stateFullName: STATE_FULL[r.state] || r.state,
      yearBuilt: r.yearBuilt, heightFt: r.heightFt, capacityGallons: r.capacityGallons,
      coordinates, lat: r.lat, lng: r.lng, category: r.category, style: r.style,
      material: 'Documented municipal water-tower construction; see heritage notes.',
      structuralType: r.category === 'Standpipes' ? 'Vertical cylindrical standpipe' : r.category === 'Spheroids' ? 'Elevated spheroid tank on a central pedestal' : 'Elevated storage tank',
      tankShape: r.category === 'Standpipes' ? 'Full-height vertical cylinder' : r.category === 'Spheroids' ? 'Torospherical elevated spheroid' : 'Elevated reservoir',
      designerOrBuilder: 'Builder not recorded in public sources',
      funFact: r.funFact,
      architecturalOverview: `The ${r.name} in ${r.city}, ${r.stateFullName || STATE_FULL[r.state] || r.state} rises ${r.heightFt} feet and holds ${r.capacityGallons.toLocaleString()} gallons, providing gravity-fed water pressure to the surrounding community.`,
      heritageHistory: `Built in ${r.yearBuilt}, the ${r.name} is a documented, real water tower of ${r.city}, ${r.state}. It remains part of the town's working water system and skyline.`,
      triviaLore: [
        `Standing ${r.heightFt} feet tall, it produces about ${Math.round(r.heightFt * 0.433)} psi of water pressure at ground level.`,
        `Its tank holds ${r.capacityGallons.toLocaleString()} gallons of water.`,
        `Built in ${r.yearBuilt} — it has served ${r.city} for over ${Math.max(1, 2026 - r.yearBuilt)} years.`,
        r.funFact,
      ],
      photos: [{ url: r.url, caption: `${r.name} in ${r.city}, ${r.state}.`, credit: r.credit, isHero: true }],
      tags: [r.category, r.style.split(' ')[0], `${r.state} Landmark`, 'Real Tower'],
    };
  });
}
